mutation {
         orderUpdate(input: {
            id: "gid://shopify/Order/123456",
            shippingAddress: {
               address1: "123 Main St"
               city: "Anytown"
               country: "US"
               zip: "12345"
            }
         }) {
            order {
               id
               totalPrice
               taxesIncluded
               shippingAddress {
                  address1
                  city
                  country
                  zip
               }
            }
         }
      }
